head.script:
scwin.onpageload = function() {

};

scwin.trigger1_onclick = function(e) {
tabcontrol1.addTab("test1",
							{
								"label": "test1",
								"openAction": "exist",
								"closable": "true"
							},
							{
								"src": "tabControl_mapChart_always_WESE-474_(WSQ-5411)_sub1.xml",
								"frameMode" : "wframePreload",
								"scope" : true,
								"alwaysDraw": "true",
								"dataObject":{
									"type" : "json",
									"name" : "tabParam",
									"data" : {
										"a" : "aaaa"
									}
								}
							}
					);
};

scwin.trigger2_onclick = function(e) {
tabcontrol1.addTab("test2",
							{
								"label": "test2",
								"openAction": "exist",
								"closable": "true"
							},
							{
								"src": "tabControl_mapChart_always_WESE-474_(WSQ-5411)_sub2.xml",
								"frameMode" : "wframePreload",
								"scope" : true,
								"alwaysDraw": "true",
								"dataObject":{
									"type" : "json",
									"name" : "tabParam",
									"data" : {
										"a" : "aaaa"
									}
								}
							}
					);
};


	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('tabcontrol1_contents_test1_body_wq_uuid_11_svg').getAttribute('width') != '0';
	}	
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('tabcontrol1_contents_test1_body_wq_uuid_11_svg').getAttribute('height') != '0';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabcontrol1_tab_test1').click()");
		WebSquare.wUnit.addCommand("pause", "400");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");	
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
